const S1=[
{t:"Recognise Your Strengths",kw:["kekuatan","strength","bakat","s.i.g.n","sign","potensi"],
 ind:["Definisi dan pentingnya mengenali kelebihan diri","Cara memetakan potensi dan bakat","Penerapan kekuatan diri dalam karier dan keseharian"],
 judul:"Memaksimalkan Potensi: Strategi Mengenali dan Membangun Kekuatan Diri (<i>Strengths Building</i>)",
 intro:"<b>Cara pandang soal pengembangan diri.</b> Banyak orang menghabiskan waktu untuk menambal kelemahan (<i>weakness fixing</i>) sampai lupa membangun kekuatannya sendiri (<i>strengths building</i>). Padahal, kalau kamu fokus mengasah kekuatan, kemampuanmu tumbuh jauh lebih cepat dan kamu tidak gampang kehabisan tenaga (<i>burnout</i>).",
 bagian:[
  {h:"Definisi kekuatan diri (<i>Strength</i>)",isi:"<p>Kekuatan itu bukan cuma “hal yang bisa aku kerjakan”. Kekuatan adalah aktivitas yang kamu kerjakan dengan sangat baik, berulang kali, dan justru bikin kamu tambah semangat.</p><p>Rumusnya sederhana: Bakat Alami (<i>Talent</i>) dikali Investasi Waktu (<i>Investment</i>) sama dengan Kekuatan (<i>Strength</i>).</p>"},
  {h:"Mengidentifikasi tanda-tanda kekuatan (Metode S.I.G.N)",isi:"<ul><li><b>S (<i>Success</i>):</b> hasil kerjamu di bidang itu bagus, memuaskan, dan biasanya di atas rata-rata.</li><li><b>I (<i>Instinct</i>):</b> kamu sudah tertarik dan bersemangat bahkan sebelum mulai mengerjakannya.</li><li><b>G (<i>Growth</i>):</b> kamu cepat paham dan terus berkembang setiap kali mempelajarinya.</li><li><b>N (<i>Needs</i>):</b> setelah selesai, kamu merasa puas dan energimu seperti terisi lagi, bukan terkuras.</li></ul>"},
  {h:"Strategi memetakan potensi diri",isi:"<p>Mulai dari dirimu sendiri: ingat-ingat kegiatan apa yang bikin kamu larut sampai lupa waktu (kondisi <i>flow</i>). Setelah itu, tanyakan pendapat jujur dari teman kerja, guru, atau mentor tentang hal yang menurut mereka paling kamu kuasai.</p>"},
  {h:"Penerapan dalam keseharian",isi:"<p>Pakai kekuatan utamamu untuk memilih jurusan kuliah atau peran di tim. Untuk kelemahan, kamu tidak harus menutupinya sendirian: cari rekan tim yang kuat di bagian itu dan bekerja sama dengannya.</p>"}],
 konsep:{at:0,isi:"<b>Bakat Alami (<i>Talent</i>) × Investasi Waktu (<i>Investment</i>) = Kekuatan (<i>Strength</i>).</b> Kekuatan adalah hal yang kamu kerjakan dengan sangat baik, berulang kali, dan bikin kamu makin semangat."},
 vis:{at:1,d:"sign",cap:"Kekuatan tumbuh dari bakat yang terus dilatih. Tandanya ada empat: Success, Instinct, Growth, Needs."},
 contoh:{at:3,isi:"<p>Dina, lulusan SMK Multimedia, sedang menyusun CV. Ia mengingat masa praktik kerja lapangan: hasil desain posternya paling sering dipakai (<i>Success</i>), ia sudah bersemangat sejak brief diberikan (<i>Instinct</i>), cepat menguasai fitur baru aplikasi desain (<i>Growth</i>), dan justru merasa segar setelah selesai (<i>Needs</i>). Mentornya juga memuji kerapiannya.</p><p>Dina menonjolkan desain grafis sebagai kekuatan utama di CV dan melamar posisi desainer junior. Untuk kelemahannya dalam presentasi, ia berlatih bersama teman yang pandai berbicara.</p>"},
 poin:"Kekuatan itu bakat yang terus kamu latih. Kenali lewat S.I.G.N, lalu jadikan pegangan untuk memilih arah karier."},
{t:"Thoughts, Feelings, & What You Do",kw:["pikiran","perasaan","segitiga kognitif","self-talk","tindakan"],
 ind:["Konsep Segitiga Kognitif (Pikiran, Perasaan, Tindakan)","Dampak pola pikir terhadap munculnya emosi","Mengelola respons perilaku secara sadar"],
 judul:"Segitiga Kognitif: Memahami Siklus Pikiran, Perasaan, dan Perilaku",
 intro:"<b>Apa itu segitiga kognitif.</b> Sebuah kejadian pada dasarnya netral. Yang membuat kita merespons dengan baik atau buruk adalah cara kita memikirkan kejadian itu di kepala.",
 bagian:[
  {h:"Koneksi pikiran dan perasaan",isi:"<p>Emosi seperti marah, sedih, cemas, atau senang tidak muncul tiba-tiba. Emosi dipicu oleh obrolan di dalam kepala kita sendiri (<i>self-talk</i>) sesaat setelah sesuatu terjadi.</p>"},
  {h:"Dampak perasaan terhadap tindakan",isi:"<p>Perasaan yang muncul akan langsung mendorong apa yang kita lakukan. Misalnya, pikiran “aku pasti gagal” bikin kamu cemas, lalu kecemasan itu bikin kamu menunda-nunda pekerjaan (<i>procrastination</i>).</p>"},
  {h:"Kesadaran diri (<i>Self-Awareness</i>) dalam merespons",isi:"<p>Biasakan berhenti sebentar (<i>pause</i>) sebelum bereaksi. Di jeda itu, coba perhatikan pikiran apa yang barusan muncul, supaya kamu tidak langsung terbawa emosi sesaat.</p>"},
  {h:"Strategi memutus siklus negatif",isi:"<p>Kalau pikiran otomatismu keliru, ganti dengan kalimat yang lebih masuk akal dan lebih adil untuk dirimu sendiri. Begitu pikirannya berubah dari awal, perasaanmu ikut lebih tenang, dan tindakanmu pun lebih tepat.</p>"}],
 konsep:{at:-1,isi:"<b>Kejadian (netral) → Pikiran → Perasaan → Tindakan.</b> Yang menentukan responsmu bukan kejadiannya, tetapi cara kamu memikirkannya. Ubah pikirannya sejak awal, maka perasaan dan tindakanmu ikut berubah."},
 vis:{at:0,d:"segitiga",cap:"Segitiga kognitif: kejadian yang netral dimaknai lewat pikiran, pikiran memicu perasaan, lalu perasaan mendorong tindakan."},
 contoh:{at:1,isi:"<p>Besok Bayu ada tes wawancara kerja. Ia berpikir, “Pasti aku gagal lagi seperti kemarin” (pikiran). Ia jadi cemas dan gelisah (perasaan), lalu menghabiskan malam dengan bermain gim alih-alih menyiapkan jawaban (tindakan: <i>procrastination</i>).</p><p>Saat Bayu mengambil jeda dan mengganti pikirannya menjadi “Wawancara kemarin memberiku gambaran pertanyaan yang biasa muncul”, cemasnya berkurang dan ia mulai berlatih menjawab.</p>"},
 poin:"Yang menentukan responsmu bukan kejadiannya, tetapi cara kamu memikirkannya."},
{t:"Change Your Thinking",kw:["thinking trap","jebakan pikiran","reframing","growth mindset","catch","mindset"],
 ind:["Mengenali distorsi atau jebakan pikiran (<i>Thinking Traps</i>)","Teknik merestrukturisasi pikiran (<i>Cognitive Reframing</i>)","Membangun <i>Growth Mindset</i>"],
 judul:"Restrukturisasi Kognitif: Mengatasi Jebakan Pikiran dan Membangun <i>Growth Mindset</i>",
 intro:"<b>Pikiran tidak selalu sama dengan kenyataan.</b> Cara kita mencerna informasi sering dipengaruhi bias. Apa yang kita pikirkan belum tentu fakta; bisa jadi itu cuma tafsiran kita sendiri yang keliru dan malah menghambat kita.",
 bagian:[
  {h:"Mengenali distorsi atau jebakan pikiran (<i>Thinking Traps</i>)",isi:"<p>Jebakan pikiran adalah pola pikir otomatis yang negatif dan tidak masuk akal. Yang paling sering muncul:</p><ul><li><b><i>All-or-Nothing</i> (<i>Black-and-White Thinking</i>):</b> melihat segala sesuatu secara ekstrem, seolah pilihannya cuma berhasil sempurna atau gagal total.</li><li><b><i>Catastrophizing</i>:</b> selalu membayangkan kemungkinan terburuk dari kejadian kecil yang kurang enak.</li><li><b><i>Mind Reading</i>:</b> merasa tahu orang lain sedang berpikir buruk tentang kita, padahal tidak ada buktinya.</li><li><b><i>Personalization</i>:</b> terlalu menyalahkan diri sendiri atas kejadian buruk yang sebenarnya di luar kendali kita.</li></ul>"},
  {h:"Teknik merestrukturisasi pikiran (<i>Cognitive Reframing</i>)",isi:"<p>Tiga langkah praktis untuk melawan jebakan pikiran:</p><ul><li><b><i>Catch it</i>:</b> sadari pikiran negatif itu tepat saat ia muncul.</li><li><b><i>Check it</i>:</b> uji pikiran itu. Tanyakan pada dirimu, ini fakta atau cuma dugaan karena takut dan cemas?</li><li><b><i>Change it</i>:</b> ganti kalimat di kepalamu dengan versi yang lebih masuk akal, seimbang, dan mengarah ke jalan keluar.</li></ul>"},
  {h:"Membangun <i>Growth Mindset</i>",isi:"<p>Kenali bedanya <i>Fixed Mindset</i>, yaitu keyakinan bahwa kecerdasan dan bakat sudah dari sananya dan tidak bisa berubah, dengan <i>Growth Mindset</i>, yaitu keyakinan bahwa kemampuan bisa terus dikembangkan lewat latihan dan kerja keras.</p>"},
  {h:"Strategi implementasi <i>Growth Mindset</i>",isi:"<ul><li>Hadapi tantangan, jangan menghindar hanya karena takut kelihatan tidak mampu.</li><li>Anggap kegagalan atau kritik sebagai masukan (<i>feedback</i>) untuk memperbaiki cara belajarmu, bukan serangan terhadap dirimu.</li><li>Hargai proses dan usaha yang sudah kamu keluarkan, jangan hanya melihat hasil akhirnya.</li></ul>"}],
 konsep:{at:1,isi:"<b><i>Catch it</i> → <i>Check it</i> → <i>Change it</i>.</b> Sadari pikiran negatifnya, cek apakah itu fakta atau cuma dugaan, lalu ganti dengan kalimat yang lebih masuk akal dan mengarah ke jalan keluar."},
 vis:{at:1,d:"ccc",cap:"Tiga langkah cognitive reframing: sadari, uji, lalu ganti pikiranmu."},
 contoh:{at:3,isi:"<p>Raka menerima email penolakan dari perusahaan impiannya. Pikiran pertamanya: “Aku memang tidak akan pernah diterima di mana pun” (<i>All-or-Nothing</i> sekaligus <i>Catastrophizing</i>).</p><ul><li><b><i>Catch</i>:</b> Raka menyadari pikiran itu muncul.</li><li><b><i>Check</i>:</b> faktanya, ini baru satu penolakan, dan ia sempat lolos sampai tahap wawancara.</li><li><b><i>Change</i>:</b> “Penolakan ini menyakitkan, tetapi aku bisa meminta masukan, memperbaiki jawaban wawancaraku, dan melamar lagi.”</li></ul><p>Raka berhenti menyalahkan hal di luar kendalinya dan fokus pada hal yang bisa ia ubah. Cara pandang yang meyakini hasil dipengaruhi oleh usaha sendiri ini disebut <i>internal locus of control</i>.</p>"},
 poin:"Pikiran bukan fakta. Sadari, uji, lalu ganti, dan percaya bahwa kemampuanmu masih bisa terus tumbuh."},
{t:"Problem Solving",kw:["problem solving","masalah","akar masalah","5 whys","root cause","solusi"],
 ind:["Identifikasi akar masalah (<i>Root Cause Analysis</i>)","Perumusan dan pengembangan alternatif solusi","Evaluasi dan eksekusi penyelesaian masalah"],
 judul:"<i>Problem Solving</i> Strategis: Dari Analisis Akar Masalah hingga Eksekusi Solusi",
 intro:"<b>Cara berpikir seorang <i>problem solver</i>.</b> Bereaksi spontan terhadap masalah berbeda dengan menanganinya secara terencana. Pemecahan masalah yang baik mencari jalan keluar jangka panjang, bukan “solusi plester” (<i>band-aid solution</i>) yang cuma menutupi gejalanya sebentar.",
 bagian:[
  {h:"Identifikasi akar masalah (<i>Root Cause Analysis</i>)",isi:"<p>Bedakan dulu gejala masalah (<i>symptom</i>) dengan akar masalahnya (<i>root cause</i>).</p><ul><li>Pakai teknik <i>5 Whys</i>: tanyakan “kenapa?” berulang kali sampai kamu menemukan penyebab paling dasarnya.</li><li>Tulis rumusan masalah (<i>Problem Statement</i>) yang jelas, spesifik, dan objektif, tanpa dicampur dugaan atau perasaan pribadi.</li></ul>"},
  {h:"Perumusan dan pengembangan alternatif solusi",isi:"<p>Di tahap ini, pikiranmu dibuat melebar (<i>divergent thinking</i>). Jangan langsung puas dengan ide pertama yang muncul.</p><ul><li><b>Lakukan <i>brainstorming</i>:</b> kumpulkan ide sebanyak mungkin dulu, jangan dinilai atau disaring di awal.</li><li><b>Ajak orang lain:</b> minta pendapat teman atau rekan supaya pilihan solusinya lebih banyak dan lebih beragam.</li></ul>"},
  {h:"Evaluasi dan pemilihan solusi terbaik",isi:"<p>Setelah ide terkumpul, saatnya mengerucutkan pilihan (<i>convergent thinking</i>): uji satu per satu ide yang sudah ada.</p><ul><li>Saring dengan matriks sederhana: seberapa mudah dijalankan (<i>feasibility</i>), seberapa besar dampaknya (<i>impact</i>), berapa lama waktunya, dan sumber daya apa yang kamu punya.</li><li>Pertimbangkan risiko serta untung-ruginya (<i>cost-benefit</i>) sebelum memutuskan.</li></ul>"},
  {h:"Eksekusi penyelesaian dan evaluasi akhir",isi:"<p>Sekarang ide diubah menjadi tindakan nyata.</p><ul><li><b>Buat rencana tindakan (<i>Action Plan</i>) yang jelas:</b> apa saja langkahnya, siapa yang mengerjakan, dan kapan tenggatnya.</li><li><b>Tinjau ulang (<i>Review/Monitoring</i>):</b> cek apakah solusinya benar-benar menyelesaikan akar masalah. Kalau belum, jangan kaku; perbaiki dan coba lagi (iterasi).</li></ul>"}],
 konsep:{at:0,isi:"<b>Gejala (<i>symptom</i>) ≠ akar masalah (<i>root cause</i>).</b> Tanyakan “kenapa?” berulang kali (<i>5 Whys</i>) sampai ketemu penyebab paling dasarnya, lalu tulis rumusan masalah yang jelas, spesifik, dan objektif."},
 vis:{at:3,d:"ps",cap:"Alur pemecahan masalah: cari akar masalah, kumpulkan pilihan solusi, nilai, jalankan, lalu tinjau ulang."},
 contoh:{at:0,isi:"<p>Sari sudah mengirim 20 lamaran, tetapi belum ada satu pun panggilan. Ia mencoba <i>5 Whys</i>:</p><ul><li>Mengapa tidak ada panggilan? CV-nya tidak lolos penyaringan awal.</li><li>Mengapa tidak lolos? Isi CV tidak cocok dengan kebutuhan lowongan.</li><li>Mengapa tidak cocok? Ia mengirim CV yang sama untuk semua lowongan.</li><li>Mengapa sama? Ia tidak membaca deskripsi pekerjaan dengan teliti.</li><li>Mengapa tidak teliti? Ia mengejar jumlah lamaran, bukan kesesuaian.</li></ul><p><b>Rumusan masalah:</b> “CV belum disesuaikan dengan kata kunci tiap lowongan.” Rencana tindakannya: menyesuaikan tiga CV per minggu, meminta guru BK meninjau, lalu mengevaluasi hasilnya setelah dua minggu.</p>"},
 poin:"Selesaikan akar masalahnya, jangan cuma gejalanya: cari penyebab, kumpulkan ide, pilih, jalankan, lalu tinjau lagi."},
{t:"Keeping Well",kw:["well-being","kesejahteraan","self-care","istirahat","toxic productivity","sehat"],
 ind:["Konsep dasar kesejahteraan holistik (<i>Well-being</i>)","Keseimbangan antara aktivitas dan istirahat","Strategi membangun rutinitas <i>self-care</i> berkelanjutan"],
 judul:"Kesejahteraan Holistik: Strategi Menjaga Keseimbangan Hidup dan <i>Self-Care</i> Berkelanjutan",
 intro:"<b>Apa itu kesejahteraan menyeluruh (<i>Well-being</i>).</b> <i>Well-being</i> bukan cuma soal tidak sakit. Artinya, kamu dalam kondisi baik secara fisik, mental, emosional, dan sosial. Kondisi inilah yang memberimu tenaga untuk memecahkan masalah, mengatur emosi, dan mengembangkan potensimu.",
 bagian:[
  {h:"Keseimbangan antara aktivitas dan istirahat",isi:"<p>Sibuk belum tentu produktif. Hati-hati dengan kebiasaan kerja atau belajar berlebihan (<i>toxic productivity</i>) yang sering berakhir dengan kelelahan berat (<i>burnout</i>).</p><ul><li><b>Kenali sinyal tubuh dan pikiran:</b> mudah marah, susah fokus, atau tidur terganggu adalah tanda kamu perlu berhenti sejenak sebelum jatuh sakit.</li><li><b>Pentingnya waktu jeda (<i>downtime</i>):</b> tidur cukup dan waktu santai tanpa urusan kerja itu bagian dari mengisi ulang energi dan kreativitas, bukan tanda malas.</li></ul>"},
  {h:"Miskonsepsi tentang <i>self-care</i>",isi:"<p>Merawat diri (<i>self-care</i>) bukan berarti belanja atau liburan mahal untuk kabur sebentar dari masalah. <i>Self-care</i> yang sebenarnya adalah kebiasaan dasar yang kamu lakukan dengan sadar untuk menjaga kesehatan fisik dan mentalmu.</p>"},
  {h:"Strategi membangun rutinitas <i>self-care</i> berkelanjutan",isi:"<p>Susun rencana merawat diri yang realistis dan muat di jadwal harianmu:</p><ul><li><b>Fisik:</b> olahraga ringan secara rutin, makan bergizi, dan cukup minum air.</li><li><b>Mental/emosional:</b> batasi konten negatif di media sosial, tulis jurnal, atau latihan pernapasan.</li><li><b>Sosial:</b> jaga hubungan yang hangat dengan orang-orang terdekat (<i>support system</i>) dan tetapkan batasan (<i>boundaries</i>) yang tegas dengan lingkungan yang <i>toxic</i>.</li></ul>"},
  {h:"Eksekusi dan komitmen",isi:"<p>Pilih 1–2 kebiasaan kecil, misalnya tidur lebih awal atau jalan kaki 15 menit, lalu lakukan setiap hari. Lebih baik kecil tapi rutin daripada rencana besar yang cepat ditinggalkan.</p>"}],
 vis:{at:-1,d:"well",cap:"Well-being mencakup empat aspek yang saling mendukung: fisik, mental, emosional, dan sosial."},
 konsep:{at:1,isi:"<b><i>Self-care</i> yang sebenarnya</b> adalah kebiasaan dasar yang kamu lakukan dengan sadar untuk menjaga kesehatan fisik dan mental, bukan pelarian sesaat."},
 contoh:{at:3,isi:"<p>Selama mencari kerja, Sinta begadang setiap malam mengirim lamaran. Ia mulai mudah marah dan sulit fokus saat psikotes daring. Sinta lalu memilih dua kebiasaan: tidur sebelum pukul 23.00 dan jalan kaki 15 menit setiap pagi. Ia juga membisukan akun yang membuatnya membandingkan diri dengan teman yang sudah bekerja.</p><p>Dua minggu kemudian, ia lebih tenang dan bisa menyelesaikan psikotes dengan fokus.</p>"},
 poin:"Istirahat bukan berarti malas. Kebiasaan kecil yang rutin menjaga tenagamu supaya bisa berjuang lebih lama."}];

const S2=[
{t:"Emotional and Social Awareness",kw:["kecerdasan emosional","eq","self-awareness","social awareness","emosi","trigger","reading the room"],
 ind:["Pengenalan dan pemetaan emosi diri (<i>Self-Awareness</i>)","Kepekaan membaca isyarat emosional orang lain (<i>Social Awareness</i>)","Dinamika interaksi sosial berbasis kecerdasan emosional"],
 judul:"Fondasi Kecerdasan Emosional: Mengasah <i>Self-Awareness</i> dan <i>Social Awareness</i>",
 intro:"<b>Dari mana kecerdasan emosional dimulai.</b> Kecerdasan emosional (EQ) tidak dimulai dari pandai menahan marah atau memimpin tim, tetapi dari sadar (<i>awareness</i>). Kalau kamu belum bisa menyadari apa yang terjadi di dalam dirimu dan di sekitarmu, cara mengatur emosi apa pun tidak akan banyak membantu.",
 bagian:[
  {h:"Pengenalan dan pemetaan emosi diri (<i>Self-Awareness</i>)",isi:"<ul><li><b>Kenali emosimu dengan tepat:</b> beri nama perasaanmu sejelas mungkin. Jangan berhenti di “kesal”; cari tahu apakah sebenarnya kamu kecewa, merasa tidak dihargai, atau cuma capek.</li><li><b>Kenali pemicunya (<i>triggers</i>):</b> perhatikan hal-hal yang selalu memancing reaksi negatifmu (<i>emotional triggers</i>), supaya kamu bisa bersiap sebelum emosi mengambil alih akal sehat.</li><li><b>Dengarkan sinyal tubuh:</b> jantung berdebar atau napas memendek saat panik adalah tanda awal emosi mulai naik. Itu saatnya berhenti sejenak.</li></ul>"},
  {h:"Kepekaan membaca isyarat emosional orang lain (<i>Social Awareness</i>)",isi:"<ul><li><b>Perhatikan orang di sekitarmu:</b> alihkan fokus dari dirimu sendiri dan coba tangkap apa yang dirasakan orang lain. Dari sinilah empati dimulai.</li><li><b>Baca isyarat nonverbal:</b> bahasa tubuh, nada suara, kontak mata, dan ekspresi wajah sekilas (<i>micro-expressions</i>) sering lebih jujur daripada kata-kata.</li><li><b>Baca “suhu ruangan” (<i>reading the room</i>):</b> rasakan suasana hati sebuah kelompok atau rapat, lalu sesuaikan caramu bersikap.</li></ul>"},
  {h:"Dinamika interaksi sosial berbasis kecerdasan emosional",isi:"<ul><li><b>Gabungkan keduanya:</b> pakai pengetahuan tentang dirimu (<i>self-awareness</i>, misalnya batas sabarmu) dan tentang lawan bicara (<i>social awareness</i>, misalnya suasana hatinya) untuk memilih respons yang paling pas.</li><li><b>Redakan konflik:</b> saat beda pendapat, pakai kepekaanmu untuk menurunkan ketegangan, bukan malah defensif sehingga suasananya makin panas.</li><li><b>Kelola hubungan (<i>Relationship Management</i>):</b> kepekaan sosial membantumu membangun hubungan yang tulus, kerja sama tim yang sehat, dan rasa saling percaya (<i>trust</i>).</li></ul>"}],
 konsep:{at:2,isi:"<b><i>Self-Awareness</i> + <i>Social Awareness</i> → respons yang tepat.</b> Sadar akan diri sendiri dan orang lain adalah bekal untuk mengelola hubungan (<i>Relationship Management</i>)."},
 vis:{at:2,d:"venn",cap:"Saat kesadaran diri dan kesadaran sosial bertemu, kamu bisa merespons dengan tepat dan hubunganmu tetap sehat."},
 contoh:{at:1,isi:"<p>Dalam wawancara kelompok, Bima merasa jantungnya berdebar setiap kali peserta lain memotong pembicaraannya. Ia menamai perasaannya: bukan sekadar kesal, tetapi merasa tidak dihargai. Ia mengambil napas sebelum menanggapi.</p><p>Bima juga memperhatikan seorang peserta yang sejak awal diam dan menunduk, lalu mengajaknya menyampaikan pendapat. Pewawancara mencatat Bima sebagai kandidat yang tenang, peka, dan kolaboratif.</p>"},
 poin:"Kecerdasan emosional dimulai dari sadar: kenali emosimu, baca orang lain, lalu pilih respons yang paling pas."},
{t:"Facing Stress and Burnout",kw:["stres","stress","burnout","coping","stressor","boundaries","energi"],
 ind:["Perbedaan antara stres situasional dan kelelahan kronis (<i>Burnout</i>)","Identifikasi pemicu stres (<i>stressors</i>) dan gejalanya","Strategi <i>coping mechanism</i> dan manajemen energi"],
 judul:"Manajemen Stres dan Pencegahan <i>Burnout</i>: Strategi Bertahan dan Memulihkan Energi",
 intro:"<b>Tekanan itu bagian dari hidup.</b> Tekanan saat kuliah atau bekerja itu wajar. Yang penting, kamu tahu batasnya: kapan tekanan masih bikin kamu semangat (<i>eustress</i>) dan kapan tekanan mulai merusak kesehatan mental dan fisikmu (<i>distress</i>).",
 bagian:[
  {h:"Perbedaan stres situasional dan kelelahan kronis (<i>Burnout</i>)",isi:"<ul><li><b>Stres:</b> kamu terlalu terlibat dan bereaksi berlebihan (<i>over-engagement</i>) terhadap beban yang ada. Orang yang stres masih berharap keadaan membaik setelah bebannya selesai. Gejalanya lebih ke fisik dan emosi yang terlalu aktif: cemas, panik, jantung berdebar.</li><li><b><i>Burnout</i>:</b> kamu justru menarik diri secara emosional (<i>disengagement</i>). <i>Burnout</i> adalah ujung dari stres panjang yang tidak ditangani. Tandanya: kehilangan motivasi, perasaan mati rasa (<i>blunted emotions</i>), sinis, cuek, dan merasa tidak ada jalan keluar (<i>helplessness</i>).</li></ul>"},
  {h:"Identifikasi pemicu stres (<i>stressors</i>) dan gejalanya",isi:"<ul><li><b>Kenali sumber stresmu:</b> ada yang datang dari luar (beban kerja terlalu banyak, tenggat mepet, konflik dengan orang lain, lingkungan <i>toxic</i>) dan ada yang dari dalam (perfeksionis berlebihan, <i>overthinking</i>, pesimis).</li><li><b>Tangkap gejala awalnya:</b> perhatikan “alarm tubuh”, misalnya sakit kepala, susah tidur, atau gangguan pencernaan; perubahan emosi seperti mudah tersinggung dan cemas; serta perubahan perilaku seperti menunda-nunda secara parah atau menarik diri dari teman.</li></ul>"},
  {h:"Strategi <i>coping mechanism</i> yang sehat",isi:"<ul><li><b><i>Problem-Focused Coping</i>:</b> langsung menangani sumber masalahnya, misalnya menyusun ulang prioritas, memperbaiki cara mengatur waktu, atau minta tenggat diundur.</li><li><b><i>Emotion-Focused Coping</i>:</b> menenangkan emosi saat sumber masalahnya belum bisa diubah, misalnya <i>mindfulness</i>, menarik napas dalam, curhat ke orang yang kamu percaya (<i>venting</i>), atau menulis jurnal perasaan.</li></ul>"},
  {h:"Manajemen energi dan ketegasan batasan (<i>boundaries</i>)",isi:"<ul><li>Jangan cuma mengatur waktu, atur juga energimu. Tenaga fisik dan mentalmu terbatas dan perlu diisi ulang lewat istirahat yang benar-benar berkualitas, bukan sekadar berhenti bekerja.</li><li>Tetapkan batasan (<i>setting boundaries</i>) yang sehat. Latih cara bicara yang tegas tapi sopan supaya kamu berani bilang “tidak” pada tugas tambahan yang sudah melebihi kemampuanmu.</li></ul>"}],
 konsep:{at:0,isi:"<b>Stres = terlalu terlibat (<i>over-engagement</i>)</b>, emosi terlalu aktif, tetapi masih ada harapan. <b><i>Burnout</i> = menarik diri (<i>disengagement</i>)</b>, perasaan tumpul, dan merasa tidak ada jalan keluar (<i>helplessness</i>)."},
 vis:{at:0,d:"stres",cap:"Stres yang dibiarkan berlarut-larut bisa berubah menjadi burnout."},
 contoh:{at:3,isi:"<p>Bulan pertama bekerja, Fajar mendapat tiga tugas baru dengan tenggat yang sama. Kepalanya tegang dan tidurnya terganggu.</p><ul><li><b><i>Problem-focused</i>:</b> ia menyusun prioritas dan bertanya kepada atasan tugas mana yang paling mendesak.</li><li><b><i>Emotion-focused</i>:</b> malamnya ia berlatih napas dalam dan bercerita kepada kakaknya.</li><li><b>Batasan:</b> saat diminta mengambil tugas keempat, ia menjawab sopan, “Saya bisa mengerjakannya Senin depan setelah laporan ini selesai.”</li></ul>"},
 poin:"Kenali stresmu sebelum berubah jadi burnout: tangani masalahnya, rawat perasaanmu, dan jaga batas tenagamu."},
{t:"Criticism, Weakness and Failure",kw:["kritik","kegagalan","gagal","resilience","resiliensi","feedback","kelemahan"],
 ind:["Mengelola respons emosional saat menerima kritik","Membangun ketahanan mental (<i>Resilience</i>) menghadapi kegagalan","Transformasi <i>feedback</i> dan kelemahan menjadi area pengembangan"],
 judul:"Ketahanan Mental: Seni Merespons Kritik dan Bangkit dari Kegagalan",
 intro:"<b>Kritik dan kegagalan pasti datang.</b> Saat belajar, berorganisasi, atau bekerja, kamu pasti pernah dikritik, sadar punya kelemahan, dan mengalami gagal. Reaksi spontan kita biasanya membela diri (menyerang balik) atau menyangkal demi menjaga gengsi. Masalahnya, reaksi seperti itu justru membuat kita berhenti berkembang.",
 bagian:[
  {h:"Mengelola respons emosional saat menerima kritik",isi:"<ul><li><b>Beri jeda (<i>pause</i>):</b> tarik napas dan diam beberapa detik sebelum menanggapi kritik. Jeda ini mencegahmu langsung sibuk mencari alasan.</li><li><b>Pisahkan isi dari cara penyampaiannya:</b> cara orang mengkritik mungkin kurang enak, tetapi isinya bisa saja fakta atau masukan yang berguna.</li><li><b>Kritik bukan serangan pribadi:</b> teguran atas hasil kerjamu tidak berarti kamu sebagai orang tidak mampu atau tidak berharga.</li></ul>"},
  {h:"Membangun ketahanan mental (<i>Resilience</i>) menghadapi kegagalan",isi:"<ul><li><b>Apa itu <i>resilience</i>:</b> ketahanan mental adalah kemampuan untuk pulih dan bangkit lagi (<i>bounce back</i>) dengan cepat setelah jatuh, bukan sekadar seberapa kuat kamu menahan sakit.</li><li><b>Gagal itu kejadian, bukan identitas:</b> “aku gagal hari ini” sangat berbeda dengan “aku orang yang gagal”. Kegagalan adalah peristiwa (<i>event</i>), bukan cap yang menempel selamanya.</li><li><b>Evaluasi dengan kepala dingin (<i>Post-Mortem Analysis</i>):</b> daripada menyesali nasib atau menyalahkan keadaan, tanyakan: “Apa saja yang meleset?”, “Apa yang bisa aku pelajari?”, dan “Apa yang perlu kuubah di kesempatan berikutnya?”</li></ul>"},
  {h:"Transformasi <i>feedback</i> dan kelemahan menjadi area pengembangan",isi:"<ul><li><b>Terima dulu (<i>acceptance</i>):</b> semua orang punya titik buta (<i>blind spot</i>) yang hanya terlihat oleh orang lain. Menerima kelemahan tanpa malu adalah langkah pertama untuk memperbaikinya.</li><li><b>Ambil pelajaran yang bisa langsung dipraktikkan (<i>actionable insights</i>):</b> ubah masukan yang masih umum menjadi langkah yang jelas. Misalnya, kritik “presentasimu membosankan” diubah jadi target “aku perlu melatih intonasi dan membuat slide yang lebih menarik”.</li><li><b>Susun rencana bertumbuh (<i>Growth Plan</i>):</b> kumpulkan kritik dan kelemahan yang sudah kamu sadari, lalu jadikan peta jalan (<i>roadmap</i>) untuk menentukan keterampilan apa yang mau kamu pelajari berikutnya.</li></ul>"}],
 vis:{at:0,d:"kritik",cap:"Dari kritik ke rencana bertumbuh: beri jeda, pisahkan isi pesannya, ambil pelajarannya, lalu susun rencana."},
 konsep:{at:1,isi:"<b>Kegagalan adalah peristiwa (<i>event</i>), bukan identitas.</b> <i>Resilience</i> adalah kemampuan untuk bangkit lagi (<i>bounce back</i>) setelah jatuh, bukan sekadar menahan sakit."},
 contoh:{at:1,isi:"<p>Lia gagal di tahap psikotes sebuah BUMN. Awalnya ia berpikir, “Aku memang bodoh.” Ia lalu melakukan <i>post-mortem</i>:</p><ul><li><b>Apa yang meleset?</b> Ia kehabisan waktu di bagian hitungan dan tidak pernah berlatih soal berwaktu.</li><li><b>Apa pelajarannya?</b> Kecepatan bisa dilatih; ini soal persiapan, bukan identitas.</li><li><b>Apa yang diubah?</b> Latihan 20 soal berwaktu setiap hari selama dua minggu sebelum tes berikutnya.</li></ul>"},
 poin:"Kritik itu masukan, kegagalan itu kejadian. Ambil pelajarannya, lalu bangkit lagi."},
{t:"Happiness in Life",kw:["bahagia","kebahagiaan","happiness","syukur","gratitude","bermakna"],
 ind:["Makna kebahagiaan sejati dan kepuasan hidup (<i>Life Satisfaction</i>)","Praktik rasa syukur (<i>Gratitude</i>) untuk kesejahteraan psikologis","Strategi menciptakan kebahagiaan yang bermakna (<i>Meaningful Life</i>)"],
 judul:"Psikologi Kebahagiaan: Mewujudkan Kepuasan Hidup dan Kesejahteraan yang Bermakna",
 intro:"<b>Salah kaprah soal bahagia.</b> Banyak orang mengira bahagia berarti selalu senang, tanpa pernah sedih atau marah. Padahal, bahagia yang sebenarnya justru mencakup kemampuan menerima semua jenis perasaan sambil tetap merasa tenang di dalam hati.",
 bagian:[
  {h:"Makna kebahagiaan sejati dan kepuasan hidup (<i>Life Satisfaction</i>)",isi:"<ul><li>Bedakan kebahagiaan hedonis, yaitu senang sesaat dari hal di luar diri seperti hiburan atau barang, dengan kebahagiaan eudaimonik, yaitu rasa puas yang dalam karena kamu mengembangkan potensimu dan menjalani tujuan hidupmu.</li><li>Kepuasan hidup (<i>life satisfaction</i>) muncul saat harapanmu sejalan dengan kenyataan dan kamu bisa berdamai dengan hal-hal yang tidak bisa diubah.</li></ul>"},
  {h:"Praktik rasa syukur (<i>Gratitude</i>) untuk kesejahteraan psikologis",isi:"<ul><li><b>Bersyukur mengubah fokus:</b> otak kita cenderung lebih memperhatikan hal yang kurang atau salah (<i>negativity bias</i>). Kalau rutin bersyukur, otak terlatih (<i>rewire</i>) untuk melihat hal baik yang sudah kamu punya.</li><li><b>Cara mempraktikkannya:</b> tulis jurnal syukur (<i>gratitude journaling</i>). Mencatat 3–5 hal kecil yang kamu syukuri setiap hari terbukti bisa menurunkan hormon stres (kortisol) dan membuat perasaan lebih baik.</li></ul>"},
  {h:"Strategi menciptakan kebahagiaan yang bermakna (<i>Meaningful Life</i>)",isi:"<ul><li><b>Temukan alasanmu (<i>Finding Your Why</i>):</b> bahagia sering datang sebagai “bonus” (<i>byproduct</i>) dari hidup yang bermakna. Hubungkan kegiatan sehari-hari, seperti kuliah atau bekerja, dengan nilai-nilai yang kamu pegang (<i>core values</i>).</li><li><b>Bangun hubungan yang tulus:</b> salah satu hal yang paling menentukan kebahagiaan adalah kualitas hubunganmu dengan orang lain. Luangkan waktu dan perhatian untuk keluarga, pasangan, atau sahabat.</li><li><b>Berbagi dan membantu (altruisme):</b> bahagia yang bertahan lama sering muncul saat kita berhenti hanya memikirkan diri sendiri dan mulai membantu orang di sekitar kita.</li></ul>"}],
 konsep:{at:0,isi:"<b>Hedonis vs eudaimonik.</b> Kebahagiaan hedonis adalah senang sesaat dari hal di luar diri; kebahagiaan eudaimonik adalah rasa puas yang dalam karena mengembangkan potensi dan menjalani tujuan hidup."},
 vis:{at:2,d:"bahagia",cap:"Hidup yang bermakna bertumpu pada tiga hal, dengan rasa syukur sebagai dasarnya."},
 contoh:{at:2,isi:"<p>Tiga bulan setelah lulus, Arif merasa tertinggal karena teman-temannya sudah bekerja. Ia mulai menulis tiga hal yang disyukuri setiap malam, misalnya lolos seleksi berkas, masakan ibu, dan teman yang membantu meninjau CV.</p><p>Ia juga menyadari “mengapa”-nya: ia ingin bekerja di bidang kelistrikan karena senang memperbaiki alat dan ingin membantu keluarga. Sambil menunggu panggilan, ia menjadi relawan memperbaiki instalasi listrik di musala dekat rumah. Rasa tertinggalnya berganti menjadi rasa berarti.</p>"},
 poin:"Bahagia tidak harus selalu senang. Bahagia adalah hidup yang bermakna: bersyukur, punya hubungan yang hangat, dan bermanfaat bagi orang lain."},
{t:"Communicate with Empathy",kw:["empati", "simpati", "mendengarkan", "active listening", "validasi emosi", "paraphrasing", "asertif", "i-message", "komunikasi", "welas asih"],
 ind:["Prinsip dasar empati dalam interaksi sosial", "Teknik mendengarkan aktif (<i>Active Listening</i>) tanpa menghakimi", "Strategi merespons lawan bicara secara asertif dan welas asih"],
 judul:"Seni Mendengarkan Aktif dan Merespons dengan Welas Asih",
 intro:"<b>Inti komunikasi yang berempati.</b> Komunikasi yang baik bukan cuma soal seberapa rapi kamu bicara, tetapi seberapa paham kamu dengan sudut pandang dan perasaan lawan bicara. Empati adalah jembatan supaya tidak terjadi konflik dan salah paham, entah dengan rekan kerja, atasan, atau pelanggan.",
 bagian:[
  {h:"Prinsip dasar empati dalam interaksi sosial",isi:"<ul><li><b>Simpati vs. empati:</b> simpati berarti merasa kasihan dari sudut pandang kita sendiri (“Kasihan ya kamu”). Empati berarti mencoba berdiri di posisi orang lain, baik dengan memahami cara berpikirnya (kognitif) maupun ikut merasakan perasaannya (emosional).</li><li><b>Validasi emosi:</b> akui bahwa perasaan lawan bicara itu nyata dan penting baginya, meskipun kamu belum tentu setuju dengan sumber masalahnya. Contohnya, “Wajar kamu kecewa, kamu sudah menyiapkannya berhari-hari.”</li></ul>"},
  {h:"Teknik mendengarkan aktif (<i>Active Listening</i>) tanpa menghakimi",isi:"<ul><li><b>Dengarkan untuk memahami:</b> jangan cuma diam menunggu giliran bicara sambil menyusun balasan di kepala. Pusatkan perhatianmu pada apa yang sedang diceritakan.</li><li><b>Hadir sepenuhnya (<i>presence</i>):</b> jaga kontak mata, jauhkan ponsel, dan beri respons nonverbal seperti mengangguk dan menghadapkan badan ke lawan bicara.</li><li><b>Tahan asumsi:</b> jangan memotong, jangan mengecilkan masalahnya (misalnya “Ah, gitu doang”), dan jangan buru-buru menasihati kalau dia sebenarnya hanya ingin didengar.</li></ul>"},
  {h:"Strategi merespons lawan bicara secara asertif dan welas asih",isi:"<ul><li><b>Teknik <i>paraphrasing</i>:</b> pastikan kamu paham dengan merangkum ulang ceritanya pakai kalimatmu sendiri, misalnya “Jadi, yang bikin kamu tertekan itu tenggatnya dimajukan, ya?”</li><li><b>Komunikasi asertif:</b> sampaikan pendapat atau batasanmu dengan jelas, tetapi tetap menghargai perasaan orang lain. Pakai pesan “saya” (<i>I-Message</i>), misalnya “Saya khawatir laporan kita terlambat”, bukan kalimat menuduh seperti “Kamu selalu telat!”</li></ul>"}],
 konsep:{at:1,isi:"<b>Dengarkan dulu, baru tanggapi:</b> hadir sepenuhnya → pahami tanpa menghakimi → ulangi dengan kalimatmu sendiri → akui perasaannya. Setelah lawan bicara merasa dipahami, sampaikan pendapatmu dengan tegas lewat pesan “saya”."},
 vis:{at:1,d:"listen",cap:"Langkah mendengarkan aktif supaya lawan bicara merasa dipahami."},
 contoh:{at:2,isi:"<p>Saat magang, rekan setim Gita belum menyerahkan bagian laporannya, padahal tenggatnya besok.</p><ul><li><b>Agresif:</b> “Kamu selalu telat! Gara-gara kamu kita bisa kena tegur.”</li><li><b>Pasif:</b> Gita diam dan mengerjakan bagian rekannya sendirian sampai larut malam.</li><li><b>Asertif dan welas asih:</b> “Aku lihat kamu kelihatan capek akhir-akhir ini. Bagianmu belum masuk, dan aku khawatir laporan kita telat besok. Ada yang bisa kubantu supaya selesai sore ini?”</li></ul>"},
 poin:"Berempati tidak sama dengan selalu setuju. Dengarkan untuk memahami, akui perasaannya, lalu sampaikan pendapatmu dengan tegas tanpa menyakiti."}];

const S3=[
{t:"System Thinking",kw:["system thinking", "berpikir sistem", "feedback loop", "reinforcing", "balancing", "delay", "iceberg", "gunung es", "linear", "holistik"],
 ind:["Definisi dan perbedaan <i>System Thinking</i> dibandingkan pola pikir linear", "Analisis elemen sistem dan hubungan sebab-akibat (<i>Feedback Loops</i>)", "Pemetaan masalah secara komprehensif untuk menghasilkan solusi holistik"],
 judul:"Memahami Kausalitas dan Merancang Solusi Holistik",
 intro:"<b>Melihat masalah sebagai sistem.</b> Banyak masalah di tempat kerja tidak selesai-selesai karena yang diobati hanya gejalanya. Berpikir sistem (<i>System Thinking</i>) mengajakmu melihat bahwa setiap bagian saling terhubung, supaya solusi yang kamu pilih mengenai akar masalah dan tidak memunculkan masalah baru.",
 bagian:[
  {h:"Definisi dan perbedaan <i>System Thinking</i> dibandingkan pola pikir linear",isi:"<ul><li><b>Pola pikir linear:</b> melihat masalah seperti garis lurus (A menyebabkan B) dan mencari solusi cepat untuk jangka pendek. Cara ini sering hanya menambal gejala tanpa memikirkan dampak berikutnya.</li><li><b><i>System Thinking</i>:</b> melihat sesuatu sebagai satu kesatuan yang bagian-bagiannya saling terhubung. Kalau satu bagian berubah, bagian lain ikut terpengaruh.</li></ul>"},
  {h:"Analisis elemen sistem dan hubungan sebab-akibat (<i>Feedback Loops</i>)",isi:"<ul><li><b>Elemen pembentuk sistem:</b> setiap sistem punya <b>komponen</b> (bagian-bagiannya, misalnya orang, alat, aturan), <b>interkoneksi</b> (hubungan antarbagian), dan <b>tujuan</b> atau fungsi utamanya.</li><li><b>Siklus umpan balik (<i>feedback loops</i>):</b> sebab-akibat jarang berjalan satu arah. Biasanya melingkar: akibat kembali memengaruhi sebabnya.<ul><li><b><i>Reinforcing loop</i> (siklus penguat):</b> kondisi yang membuat dampaknya makin besar, bisa ke arah baik (tumbuh) atau buruk (makin parah). Contohnya, makin sering latihan wawancara, makin lancar menjawab, makin percaya diri, jadi makin rajin berlatih.</li><li><b><i>Balancing loop</i> (siklus penyeimbang):</b> kecenderungan sistem untuk kembali stabil atau menolak perubahan. Contohnya, makin lelah, produktivitas turun, kamu istirahat, lalu tenagamu pulih lagi.</li></ul></li><li><b>Jeda waktu (<i>delay</i>):</b> hasil sebuah keputusan sering baru terlihat belakangan. Kalau kamu sadar soal ini, kamu tidak buru-buru menganggap solusinya gagal.</li></ul>"},
  {h:"Pemetaan masalah secara komprehensif untuk menghasilkan solusi holistik",isi:"<p><b>Model Gunung Es (<i>The Iceberg Model</i>)</b> membantumu membedah masalah dari yang paling terlihat sampai yang paling dalam:</p><ol><li><b><i>Event</i>:</b> kejadian yang tampak di permukaan.</li><li><b><i>Pattern</i>:</b> pola atau tren yang terus berulang.</li><li><b><i>Underlying Structure</i>:</b> sistem, aturan, atau prosedur yang membuat pola itu terjadi.</li><li><b><i>Mental Model</i>:</b> keyakinan atau nilai yang mendasari sistem tersebut.</li></ol><p><b>Merumuskan solusi holistik:</b> dari hasil pemetaan itu, rancang langkah yang menyelesaikan akar masalah sampai tuntas dan bertahan lama, tanpa menimbulkan akibat yang tidak diinginkan (<i>unintended consequences</i>) di kemudian hari.</p>"}],
 konsep:{at:1,isi:"<b>Siklus umpan balik (<i>feedback loop</i>)</b> terjadi saat akibat kembali memengaruhi sebabnya. Siklus penguat (<i>reinforcing</i>) membuat dampak makin besar; siklus penyeimbang (<i>balancing</i>) menjaga keadaan tetap stabil. Ingat juga ada jeda waktu (<i>delay</i>) sebelum hasilnya kelihatan."},
 vis:{at:1,d:"sistem",cap:"Pola pikir linear melihat satu arah; berpikir sistem melihat siklus sebab-akibat yang saling memengaruhi."},
 contoh:{at:2,isi:"<p>Di kafe tempat Nanda magang, pelanggan sering mengeluh pesanan lambat. Solusi linear: menambah kasir. Nanda memetakan masalahnya dengan Model Gunung Es:</p><ul><li><b><i>Event</i>:</b> hari ini ada tiga keluhan pesanan terlambat.</li><li><b><i>Pattern</i>:</b> keluhan selalu muncul pukul 12.00–13.00.</li><li><b><i>Underlying Structure</i>:</b> pesanan daring menumpuk saat jam makan siang, barista kewalahan, pesanan salah dan harus dibuat ulang, sehingga antrean makin panjang. Ini siklus penguat yang negatif.</li><li><b><i>Mental Model</i>:</b> “Semua pesanan daring harus selalu diterima.”</li></ul><p>Solusi holistiknya bukan menambah kasir, melainkan menyiapkan bahan sebelum jam ramai dan membatasi pesanan daring pada jam sibuk. Keluhan turun tanpa menambah karyawan dan tanpa memunculkan masalah baru.</p>"},
 poin:"Lihat hubungannya, bukan hanya potongannya. Telusuri gunung esnya sampai ke akar, lalu pilih solusi yang tidak memicu masalah baru."},
{t:"Critical Thinking",kw:["critical thinking", "berpikir kritis", "fakta", "opini", "asumsi", "bias", "confirmation bias", "fallacy", "ad hominem", "bandwagon", "strawman", "hoaks", "penipuan", "argumen"],
 ind:["Fondasi berpikir kritis: membedakan fakta, opini, dan asumsi", "Identifikasi bias kognitif dan kesesatan logika (<i>Logical Fallacy</i>)", "Evaluasi informasi dan penyusunan argumen berbasis data dan bukti yang valid"],
 judul:"Membedah Fakta, Bias Kognitif, dan Logika Argumen",
 intro:"<b>Kenapa berpikir kritis penting sekarang.</b> Berpikir kritis bukan berarti hobi mengkritik atau mencari kesalahan orang. Berpikir kritis artinya menimbang informasi dengan tenang dan objektif sebelum mempercayainya. Di tengah banjir informasi dan hoaks, termasuk lowongan kerja palsu, kemampuan ini melindungimu supaya tidak gampang dibohongi.",
 bagian:[
  {h:"Fondasi dasar: membedakan fakta, opini, dan asumsi",isi:"<p>Pilah dulu informasi yang kamu terima:</p><ul><li><b>Fakta:</b> pernyataan yang bisa dibuktikan lewat data, pengamatan, atau ukuran yang jelas.</li><li><b>Opini:</b> pernyataan yang berasal dari perasaan, penilaian, atau tafsiran pribadi seseorang.</li><li><b>Asumsi:</b> keyakinan yang dianggap benar padahal belum ada buktinya. Langkah pertama berpikir kritis adalah berani mempertanyakan asumsi.</li></ul>"},
  {h:"Identifikasi bias kognitif dan kesesatan logika (<i>Logical Fallacy</i>)",isi:"<ul><li><b>Bias kognitif:</b> otak suka mengambil “jalan pintas” yang ujungnya membuat penilaian kita keliru. Yang paling sering terjadi adalah <b><i>confirmation bias</i></b>, yaitu kebiasaan tanpa sadar hanya mencari, mempercayai, dan mengingat informasi yang cocok dengan keyakinan kita, sambil mengabaikan fakta yang berlawanan.</li><li><b>Kesesatan logika (<i>logical fallacy</i>)</b> adalah kesalahan dalam cara menyusun alasan. Hati-hati dengan tiga jebakan ini:<ul><li><b><i>Ad hominem</i>:</b> menyerang pribadi atau fisik lawan bicara, bukan membahas isi argumennya.</li><li><b><i>Bandwagon fallacy</i>:</b> menganggap sesuatu benar hanya karena “semua orang juga begitu” atau karena sedang viral.</li><li><b><i>Strawman fallacy</i>:</b> memelintir, menyederhanakan, atau membesar-besarkan argumen orang lain supaya gampang diserang.</li></ul></li></ul>"},
  {h:"Evaluasi informasi dan penyusunan argumen berbasis data",isi:"<ul><li><b>Cek sumbernya:</b> lihat rekam jejak sumber informasi, apakah objektif, dan apakah punya kepentingan tertentu. Bandingkan dengan sumber lain yang tidak berkaitan. Untuk lowongan kerja, waspadai tanda penipuan: diminta bayar biaya pendaftaran, gaji tidak masuk akal, atau kontak “resmi” memakai email gratisan.</li><li><b>Ciri argumen yang kuat:</b> argumen yang masuk akal punya <b>premis</b> yang jelas, didukung <b>bukti</b> (data atau riset yang bisa dipercaya), dan sampai pada <b>kesimpulan</b> yang logis tanpa lompat ke kesimpulan (<i>jumping to conclusion</i>).</li></ul>"}],
 konsep:{at:0,isi:"<b>Fakta bisa dibuktikan. Opini adalah penilaian. Asumsi adalah dugaan yang belum dicek.</b> Sebelum percaya atau memutuskan, tanyakan: “Apa buktinya?”"},
 vis:{at:0,d:"foa",cap:"Matriks fakta, opini, dan asumsi beserta pertanyaan pengujinya."},
 contoh:{at:2,isi:"<p>Dodi menerima pesan berantai: “PT Maju Sentosa buka lowongan admin, gaji Rp8 juta, tanpa pengalaman. Transfer Rp150.000 untuk seragam ke rekening berikut.”</p><ul><li><b>Fakta yang bisa dicek:</b> nama perusahaan dan nomor rekening.</li><li><b>Klaim yang meragukan:</b> gaji jauh di atas rata-rata posisi pemula.</li><li><b>Pengecekan:</b> situs resmi perusahaan tidak mencantumkan lowongan tersebut, dan perusahaan resmi tidak memungut biaya rekrutmen.</li></ul><p><b>Kesimpulan:</b> kemungkinan besar penipuan. Dodi tidak mentransfer dan memperingatkan temannya.</p>"},
 poin:"Sebelum percaya, tanyakan buktinya. Pisahkan fakta dari opini dan asumsi, lalu waspadai bias dan jebakan logika."},
{t:"Strategic Thinking",kw:["strategic thinking", "berpikir strategis", "strategi", "taktik", "visi", "big picture", "peluang", "ancaman", "sumber daya", "milestone", "prioritas", "agility", "karier", "tujuan", "smart"],
 ind:["Konsep dasar visi jangka panjang dan perumusan pemikiran strategis", "Analisis situasi (pemetaan peluang, tantangan, dan kapasitas sumber daya)", "Perumusan langkah taktis untuk mencapai tujuan akhir yang efektif"],
 judul:"Menerjemahkan Visi Jangka Panjang Menjadi Langkah Taktis",
 intro:"<b>Mulai dari tujuan akhir.</b> Berpikir strategis selalu dimulai dengan membayangkan hasil yang ingin kamu capai (<i>begin with the end in mind</i>). Kamu perlu mundur sebentar untuk melihat gambaran besarnya (<i>big picture</i>) dan menentukan tujuan yang jelas, sebelum tenggelam dalam kesibukan tugas sehari-hari.",
 bagian:[
  {h:"Analisis situasi dan pemetaan kondisi",isi:"<p>Sebelum menyusun rencana, petakan dulu posisimu sekarang dengan jujur:</p><ul><li><b>Kondisi eksternal:</b> peluang (<i>opportunities</i>) yang bisa kamu manfaatkan dan ancaman atau tantangan (<i>threats</i>) yang bisa menghambatmu.</li><li><b>Kondisi internal:</b> sumber daya yang kamu punya sekarang (waktu, uang, tenaga, keahlian) dan kelemahan yang perlu diantisipasi.</li></ul>"},
  {h:"Perumusan pemikiran strategis: strategi dan taktik",isi:"<ul><li><b>Strategi:</b> arah besar tentang <i>apa</i> yang mau dicapai dan <i>mengapa</i>.</li><li><b>Taktik:</b> cara spesifik <i>bagaimana</i> strategi itu dijalankan.</li></ul><p>Strategi yang baik menghubungkan keadaanmu hari ini, dengan segala keterbatasannya, ke visi yang ingin kamu capai.</p>"},
  {h:"Perumusan langkah taktis yang efektif",isi:"<p>Ubah visi yang masih abstrak menjadi peta jalan (<i>roadmap</i>) yang konkret:</p><ul><li><b>Tonggak pencapaian (<i>milestones</i>):</b> pecah tujuan besar menjadi target jangka pendek yang jelas dan bisa diukur.</li><li><b>Prioritas tindakan:</b> pilih langkah yang dampaknya paling besar dengan sumber daya sehemat mungkin.</li></ul>"},
  {h:"Eksekusi dan kelenturan strategis (<i>agility</i>)",isi:"<p>Rencana yang baik bukan aturan kaku. Saat dijalankan, kamu boleh mengubah taktik atau pendekatan kalau keadaan tiba-tiba berubah, asal arahnya tetap menuju visi jangka panjang yang sama.</p>"}],
 konsep:{at:1,isi:"<b>Visi → analisis situasi → strategi → langkah taktis.</b> Strategi menjawab “apa dan mengapa”, taktik menjawab “bagaimana”. Keputusan karier yang realistis adalah keinginan yang sudah diuji dengan data tentang peluang, ancaman, dan sumber dayamu."},
 vis:{at:0,d:"strategi",cap:"Analisis situasi menjadi dasar langkah taktis yang bertahap menuju visi."},
 contoh:{at:3,isi:"<p>Yoga, lulusan SMK Teknik Komputer dan Jaringan, ingin menjadi <i>network engineer</i> dalam lima tahun.</p><ul><li><b>Peluang:</b> banyak penyedia internet lokal membutuhkan teknisi lapangan.</li><li><b>Ancaman:</b> perusahaan besar mensyaratkan sertifikasi dan pengalaman.</li><li><b>Sumber daya:</b> dasar jaringan yang kuat, tetapi tabungan terbatas.</li></ul><p><b>Strategi:</b> membangun pengalaman dan sertifikasi secara bertahap. <b>Langkah taktis:</b> melamar sebagai teknisi lapangan di penyedia internet lokal sambil belajar materi sertifikasi dari kursus daring gratis, dengan tonggak ujian dalam enam bulan. <b>Kelenturan:</b> jika belum diterima dalam dua bulan, ia beralih magang di bagian TI perusahaan setempat sambil tetap belajar untuk sertifikasi yang sama.</p>"},
 poin:"Tentukan tujuan akhir, baca situasi dengan jujur, pecah menjadi langkah kecil yang paling berdampak, dan tetap lentur saat situasi berubah."},
{t:"Reflective Thinking",kw:["reflective thinking", "refleksi", "berpikir reflektif", "kolb", "experiential learning", "gibbs", "introspeksi", "sense-making", "action plan", "star", "jurnal", "pengalaman"],
 ind:["Konsep siklus refleksi dan pembelajaran berbasis pengalaman (<i>Experiential Learning</i>)", "Teknik introspeksi terstruktur melalui pertanyaan evaluasi diri", "Transformasi wawasan dari pengalaman masa lalu menjadi rencana perbaikan nyata"],
 judul:"Memaknai Pengalaman dan Merancang Perbaikan Berkelanjutan",
 intro:"<b>Kenapa perlu berpikir reflektif.</b> Pengalaman saja tidak otomatis membuat orang lebih bijak atau ahli. Tanpa refleksi, pengalaman cuma jadi rutinitas yang lewat begitu saja. Berpikir reflektif berarti sengaja berhenti sejenak untuk menguraikan apa yang sudah terjadi dan mengambil pelajarannya.",
 bagian:[
  {h:"Konsep pembelajaran berbasis pengalaman (<i>Experiential Learning</i>)",isi:"<p>Siklus belajar dari pengalaman (siklus Kolb) punya empat tahap:</p><ol><li><b>Pengalaman konkret (<i>concrete experience</i>):</b> mengalami suatu kejadian.</li><li><b>Observasi reflektif (<i>reflective observation</i>):</b> mengamati kejadian itu dengan kritis.</li><li><b>Konseptualisasi abstrak (<i>abstract conceptualization</i>):</b> menarik kesimpulan atau pelajaran darinya.</li><li><b>Eksperimen aktif (<i>active experimentation</i>):</b> mencoba pelajaran itu di situasi baru.</li></ol>"},
  {h:"Teknik introspeksi terstruktur melalui pertanyaan evaluasi diri",isi:"<p>Berpikir reflektif tidak sama dengan melamun atau menyesali nasib. Evaluasi dirimu secara runtut dengan pertanyaan pemandu, seperti pada Model Refleksi Gibbs:</p><ul><li><b><i>What happened?</i></b> Ceritakan fakta kejadiannya apa adanya, tanpa dicampur asumsi.</li><li><b><i>What were you feeling and thinking?</i></b> Telusuri perasaan dan pikiran yang muncul saat itu.</li><li><b><i>What was good and bad about the experience?</i></b> Nilai sisi baik dan kurang dari caramu menghadapi situasi itu.</li></ul>"},
  {h:"Analisis mendalam (<i>sense-making</i>)",isi:"<p>Cari tahu kenapa kejadiannya berlangsung seperti itu. Temukan pola (<i>pattern</i>) dari keberhasilan dan kegagalanmu, lalu kenali keterampilan atau pengetahuan apa yang masih kurang dan memengaruhi hasilnya.</p>"},
  {h:"Transformasi wawasan menjadi rencana perbaikan nyata",isi:"<p>Refleksi jangan berhenti di perenungan. Bagian terpentingnya adalah menyusun rencana aksi (<i>action plan</i>) dengan menjawab: “Kalau situasi seperti ini terjadi lagi, apa yang akan kulakukan secara berbeda berdasarkan pelajaran hari ini?”</p><p>Saat mencari kerja, hasil refleksimu juga bisa disusun dengan metode <b>STAR</b> (<i>Situation, Task, Action, Result</i>) supaya pengalamanmu runtut dan terukur saat diceritakan di wawancara.</p>"}],
 konsep:{at:1,isi:"<b>Pengalaman + refleksi = pembelajaran.</b> Tanyakan: apa yang terjadi, apa yang kupikirkan dan rasakan, apa yang baik dan yang kurang. Lalu tutup dengan rencana aksi: apa yang akan kulakukan secara berbeda lain kali."},
 vis:{at:0,d:"kolb",cap:"Siklus Kolb: pengalaman konkret, observasi reflektif, konseptualisasi abstrak, lalu eksperimen aktif."},
 contoh:{at:3,isi:"<p>Pada wawancara pertamanya, Rina gugup ketika ditanya, “Ceritakan pengalamanmu bekerja dalam tim.” Malamnya ia berefleksi:</p><ul><li><b>Apa yang terjadi?</b> Ia menjawab berputar-putar dan lupa menyebut hasil kerjanya.</li><li><b>Apa yang ia pikirkan dan rasakan?</b> Panik, karena merasa pengalamannya “cuma PKL”.</li><li><b>Analisis:</b> ia belum pernah menyiapkan cerita pengalamannya secara runtut.</li><li><b>Rencana aksi:</b> menyusun jawaban STAR dari masa PKL. <i>Situation:</i> antrean servis di bengkel sering lebih dari dua jam. <i>Task:</i> ia bertugas mencatat antrean. <i>Action:</i> ia membuat jadwal di <i>spreadsheet</i> dan mengirim pengingat lewat WhatsApp. <i>Result:</i> waktu tunggu turun menjadi sekitar 45 menit.</li></ul>"},
 poin:"Pengalaman ditambah refleksi menjadi pembelajaran. Uraikan apa yang terjadi, rasakan, dan nilai, lalu ubah menjadi rencana aksi."},
{t:"Creative Thinking",kw:["creative thinking", "kreatif", "kreativitas", "mental block", "brainstorming", "mind map", "berpikir lateral", "lateral thinking", "combinatorial play", "inkubasi", "ide kreatif"],
 ind:["Identifikasi dan cara mengatasi hambatan kreativitas (<i>Mental Blocks</i>)", "Teknik generasi ide inovatif (seperti <i>Brainstorming</i> dan <i>Mind Mapping</i>)", "Pengembangan alternatif solusi yang adaptif dan <i>out-of-the-box</i>"],
 judul:"Mengatasi Kebuntuan Mental dan Mengembangkan Solusi Inovatif",
 intro:"<b>Kreativitas bukan bakat bawaan.</b> Berpikir kreatif tidak hanya milik seniman atau desainer. Kreativitas adalah keterampilan memecahkan masalah dari sudut pandang baru, dan bisa dilatih untuk kerja, kuliah, maupun kehidupan sehari-hari.",
 bagian:[
  {h:"Identifikasi dan cara mengatasi hambatan kreativitas (<i>Mental Blocks</i>)",isi:"<ul><li><b>Kenali hambatannya:</b> takut dikritik atau salah (<i>fear of failure</i>), terlalu terpaku pada prosedur (<i>rigid thinking</i>), dan perfeksionis sering membunuh ide sebelum sempat berkembang.</li><li><b>Cara keluar dari kebuntuan:</b> izinkan dirimu menulis ide-ide “jelek” lebih dulu, beri waktu supaya ide matang di kepala (<i>incubation period</i>), atau ganti suasana dan rutinitasmu.</li></ul>"},
  {h:"Teknik generasi ide inovatif",isi:"<ul><li><b><i>Brainstorming</i>:</b> di awal, kejar jumlah ide dulu, bukan kualitasnya. Jangan menilai atau menyaring ide selama masih mengumpulkan.</li><li><b><i>Mind mapping</i> (pemetaan pikiran):</b> tulis satu topik utama di tengah, lalu buat cabang-cabang ide di sekitarnya. Cara visual ini membantumu melihat hubungan antaride yang tidak kelihatan kalau hanya ditulis berupa daftar.</li></ul>"},
  {h:"Pengembangan alternatif solusi yang adaptif dan <i>out-of-the-box</i>",isi:"<ul><li><b>Berpikir lateral (<i>lateral thinking</i>):</b> dekati masalah dari samping atau dari sudut yang tidak terduga, bukan selalu dari depan dengan cara yang biasa.</li><li><b>Gabungkan dan sesuaikan (<i>combinatorial play</i>):</b> ambil dua atau lebih ide, produk, atau konsep yang sudah ada, lalu gabungkan menjadi solusi baru.</li><li><b>Uji idenya:</b> nilai ide-ide liar tadi, lalu ubah seperlunya supaya praktis dan bisa dijalankan di dunia nyata.</li></ul>"}],
 konsep:{at:1,isi:"<b>Cari ide sebanyak mungkin dulu, baru pilih yang terbaik.</b> Jangan menilai ide saat kamu masih mencarinya; hambatan kreativitas paling sering datang dari penilaian yang terlalu cepat."},
 vis:{at:1,d:"mind",cap:"Mind map: satu topik di tengah, lalu cabang-cabang ide di sekitarnya."},
 contoh:{at:2,isi:"<p>Tari, lulusan SMK Tata Boga, belum punya pengalaman kerja untuk dicantumkan di lamaran. Ia membuat <i>mind map</i> “Cara menunjukkan kemampuanku” dengan cabang media sosial, proyek kecil, dan acara sekolah.</p><p>Dengan <i>combinatorial play</i>, ia menggabungkan dua hal yang sudah ia kuasai, yaitu resep andalannya dan membuat video pendek, lalu menjual kue di acara sekolah. Setelah diuji, idenya ia sesuaikan: video dipersingkat menjadi 30 detik agar mudah dibagikan. Hasilnya berupa portofolio video dan testimoni pembeli yang ia lampirkan saat melamar ke toko roti.</p>"},
 poin:"Kreativitas bisa dilatih. Lepaskan hambatan, kumpulkan banyak ide, gabungkan dengan cara tak terduga, lalu uji agar bisa dijalankan."}];

const COURSE={id:0,t:"Self Development for Job Seeker",media:"GrowthLab",k:"Soft Skill",c1:"#2b55ff",
 d:"Media pembelajaran interaktif berbasis website untuk meningkatkan soft skill fresh graduate saat mencari kerja. Kamu belajar mengelola diri, mengasah kecerdasan emosional, dan melatih keterampilan berpikir lewat 15 pelajaran, latihan soal, dan simulasi kasus dunia kerja.",
 chapters:[
  {t:"Self-Management",c1:"#ff6b3d",d:"Mengenali kekuatan diri, mengelola pikiran dan perasaan, memecahkan masalah, dan menjaga kesejahteraan diri.",l:S1},
  {t:"Emotional Intelligence",c1:"#ffd23f",d:"Menyadari emosi diri dan orang lain, berkomunikasi dengan empati, serta menghadapi stres, kritik, dan kegagalan.",l:S2},
  {t:"Thinking Skill",c1:"#2b55ff",d:"Berpikir sistem, kritis, strategis, reflektif, dan kreatif untuk mengambil keputusan karier yang tepat.",l:S3}]};

const GBIM={media:"GrowthLab",judul:"Pengembangan Multimedia Interaktif Berbasis Website untuk Meningkatkan Soft Skill Fresh Graduate saat mencari kerja",jenis:"Multimedia Interaktif Berbasis Website",sasaran:"Peserta didik SMK Kelas XII",topik:"Pengembangan diri (Soft Skill)"};

/* ---------- SOAL PILIHAN GANDA (b = bab 0..2, l = pelajaran 0..4, a = indeks opsi benar sebelum diacak) ---------- */
const QUIZ=[
/* soal 1–5: dari dokumen Draft Tim 9, persis apa adanya */
{b:0,l:0,src:"pdf",q:"Menurut paradigma pengembangan diri, kekuatan diri (strength) didefinisikan sebagai.",o:["Kemampuan yang didapat murni dari keberuntungan tanpa perlu latihan","Aktivitas yang dilakukan sangat baik secara konsisten dan memberikan energi positif, hasil dari Bakat Alami dikalikan Investasi Waktu","Semua jenis pekerjaan yang diperintahkan oleh atasan dan diselesaikan tepat waktu","Kelemahan diri yang berhasil disembunyikan dari rekan kerja demi menjaga reputasi"],a:1,e:"Kekuatan adalah aktivitas yang kamu lakukan sangat baik secara konsisten dan memberi energi positif. Rumusnya: Bakat Alami × Investasi Waktu = Kekuatan."},
{b:0,l:0,src:"pdf",q:"Dalam metode S.I.G.N untuk mengidentifikasi tanda-tanda kekuatan diri, indikator Instinct ditandai oleh...",o:["Merasa lelah dan terkuras habis energinya setelah selesai bekerja","Hasil kerja yang selalu dipuji oleh banyak orang tanpa ada catatan revisi","Adanya dorongan alami, antusiasme, atau ketertarikan kuat bahkan sebelum melakukan aktivitas tersebut","Kemampuan mengingat teori sains secara cepat tanpa perlu membacanya kembali"],a:2,e:"Instinct adalah dorongan alami atau antusiasme yang muncul bahkan sebelum kamu melakukan aktivitasnya."},
{b:0,l:0,src:"pdf",q:"Bagaimana cara terbaik mengelola kelemahan diri (weakness) dalam kerja tim berdasarkan paradigma pengembangan diri?",o:["Memaksa diri mengerjakan area kelemahan tersebut sendirian tanpa bantuan","Mengelola kelemahan melalui kolaborasi dengan mencari partner tim yang kuat di area kelemahan tersebut","Menghindari semua jenis tanggung jawab dalam tim agar kelemahan tidak terlihat","Mengabaikan kelemahan dan berpura-pura bahwa kelemahan tersebut adalah kekuatan"],a:1,e:"Kelemahan dikelola lewat kolaborasi: carilah partner tim yang kuat di area kelemahanmu."},
{b:0,l:1,src:"pdf",q:"Berdasarkan konsep Segitiga Kognitif, suatu peristiwa eksternal yang kita alami pada dasarnya bersifat...",o:["Selalu bernilai negatif dan merugikan","Otomatis menentukan emosi tanpa melewati proses berpikir","Netral, di mana persepsi atau pikiran kita yang menentukan apakah responsnya menjadi positif atau negatif","Mutlak dan tidak dapat diubah oleh sudut pandang mana pun"],a:2,e:"Peristiwa itu netral. Persepsi atau pikiran kitalah yang menentukan apakah responsnya positif atau negatif."},
{b:0,l:1,src:"pdf",q:"Menurut hubungan antara pikiran dan perasaan, timbulnya gejolak emosi spesifik (seperti marah, cemas, atau bahagia) secara langsung dipicu oleh...",o:["Faktor keturunan yang diwariskan oleh orang tua","Dialog internal atau apa yang kita katakan pada diri sendiri (self-talk) tepat setelah sebuah kejadian","Cuaca dan kondisi lingkungan sekitar pada saat kejadian","Keinginan alami tubuh untuk langsung bereaksi secara fisik"],a:1,e:"Emosi dipicu oleh self-talk, yaitu apa yang kita katakan pada diri sendiri tepat setelah sebuah kejadian."},
/* soal tambahan (ditulis tim pengembang, perlu ditinjau) */
{b:0,l:2,q:"Setelah ditolak di satu perusahaan, Nadia berpikir, “Aku pasti gagal di semua lamaran berikutnya.” Jebakan pikiran (thinking trap) apa yang paling tepat menggambarkan pikiran ini?",o:["Mind Reading","Catastrophizing","Personalization","Growth Mindset"],a:1,e:"Catastrophizing berarti memprediksi skenario terburuk dari satu kejadian yang tidak menyenangkan."},
{b:0,l:2,q:"Urutan teknik Cognitive Reframing yang benar untuk menghadapi pikiran negatif setelah ditolak rekrutmen adalah...",o:["Change it → Catch it → Check it","Catch it → Check it → Change it","Check it → Catch it → Change it","Catch it → Change it → Check it"],a:1,e:"Tangkap dulu pikirannya (Catch), uji apakah berdasar fakta (Check), baru rumuskan ulang (Change)."},
{b:0,l:2,q:"Raka gagal tes wawancara dan berkata, “Percuma berusaha, hasilnya cuma soal keberuntungan.” Respons manakah yang menunjukkan internal locus of control?",o:["“Memang nasibku sedang jelek.”","“Saya akan minta masukan dan memperbaiki cara saya menjawab pertanyaan.”","“Pewawancaranya saja yang tidak teliti.”","“Saya berhenti melamar sampai punya kenalan orang dalam.”"],a:1,e:"Internal locus of control berarti meyakini bahwa hasil dipengaruhi oleh usaha sendiri, sehingga fokus pada hal yang bisa diubah."},
{b:0,l:3,q:"Langkah pertama yang paling tepat dalam pemecahan masalah terstruktur adalah...",o:["Langsung menjalankan ide solusi pertama yang muncul","Mengidentifikasi akar masalah, misalnya dengan teknik 5 Whys","Mencari siapa yang paling bersalah","Memilih solusi yang paling murah"],a:1,e:"Pemecahan masalah dimulai dengan membedakan gejala dari akar masalah, misalnya lewat 5 Whys."},
{b:0,l:3,q:"Tahap berpikir mengerucut (convergent thinking) dalam problem solving ditandai dengan kegiatan...",o:["Mengumpulkan sebanyak mungkin ide tanpa menghakimi","Menyaring alternatif berdasarkan kelayakan, dampak, waktu, dan sumber daya","Menunda keputusan sampai masalah hilang sendiri","Menutupi gejala masalah agar tidak terlihat"],a:1,e:"Convergent thinking menguji dan menyaring alternatif dengan matriks kelayakan, dampak, waktu, dan sumber daya."},
{b:0,l:4,q:"Pernyataan yang paling tepat tentang kesejahteraan holistik (well-being) adalah...",o:["Kondisi tidak sedang sakit secara fisik","Kondisi sejahtera menyeluruh yang mencakup aspek fisik, mental, emosional, dan sosial","Kemampuan bekerja tanpa istirahat","Kegiatan liburan mewah untuk melupakan masalah"],a:1,e:"Well-being bukan sekadar tidak sakit, tetapi kesejahteraan menyeluruh: fisik, mental, emosional, dan sosial."},
{b:0,l:4,q:"Setelah beberapa kali ditolak, Sinta begadang setiap malam mengirim lamaran hingga sulit fokus saat tes. Strategi self-care berkelanjutan yang paling tepat adalah...",o:["Pergi liburan mewah sekali untuk melupakan semuanya","Memilih 1–2 kebiasaan sederhana, seperti tidur lebih awal dan jalan kaki 15 menit, lalu melakukannya setiap hari","Membuat jadwal olahraga dua jam per hari mulai besok","Mengabaikan rasa lelah karena sibuk berarti produktif"],a:1,e:"Self-care yang berkelanjutan dimulai dari 1–2 kebiasaan sederhana yang dilakukan konsisten, bukan rutinitas ekstrem."},
{b:1,l:0,q:"Menurut materi, kecerdasan emosional (EQ) berawal dari...",o:["Kemampuan memimpin tim besar","Kemampuan menahan amarah sekuat mungkin","Kesadaran (awareness) atas apa yang terjadi di dalam diri dan di lingkungan sekitar","Kemampuan berbicara di depan umum"],a:2,e:"Tanpa kesadaran akan diri dan lingkungan, strategi regulasi emosi apa pun tidak akan efektif."},
{b:1,l:0,q:"Kemampuan menangkap suasana emosional kolektif dalam sebuah rapat atau kelompok disebut...",o:["Reading the room","Self-talk","Procrastination","Personalization"],a:0,e:"Reading the room adalah membaca “suhu ruangan”, yaitu suasana emosional kelompok, agar respons sesuai konteks."},
{b:1,l:4,q:"Manakah contoh mendengarkan aktif (active listening) yang paling tepat?",o:["Menyiapkan sanggahan sambil lawan bicara masih bercerita","“Jadi, yang membuatmu khawatir adalah tenggatnya, ya? Bagian mana yang paling sulit?”","Langsung memberi nasihat sebelum lawan bicara selesai","Mengecek ponsel sambil sesekali mengangguk"],a:1,e:"Mendengar aktif berarti memparafrasekan dan bertanya terbuka tanpa menghakimi."},
{b:1,l:4,q:"Rekan setim magang terlambat menyerahkan bagiannya. Respons manakah yang asertif dan welas asih?",o:["“Kamu selalu telat! Gara-gara kamu kita bisa kena tegur.”","Diam saja dan mengerjakan bagiannya sendirian sampai larut malam","“Bagianmu belum masuk dan aku khawatir laporan kita telat. Ada yang bisa kubantu supaya selesai sore ini?”","Melaporkannya ke atasan tanpa bicara dulu dengannya"],a:2,e:"Asertif berarti jujur dan tegas tentang masalahnya, sambil tetap menghormati dan menawarkan solusi bersama."},
{b:1,l:1,q:"Ciri utama burnout dibandingkan stres biasa adalah...",o:["Keterlibatan berlebihan dan jantung berdebar","Masih berharap keadaan membaik setelah beban selesai","Pelepasan diri secara emosional, mati rasa, sinis, dan merasa tidak ada jalan keluar","Merasa termotivasi oleh tenggat waktu"],a:2,e:"Burnout ditandai disengagement: motivasi hilang, emosi tumpul, sinis, apatis, dan helplessness."},
{b:1,l:1,q:"Saat magang, situasi manakah yang menunjukkan lingkungan kerja eksploitatif, bukan sekadar tekanan kerja yang wajar?",o:["Atasan memberi tenggat ketat untuk satu laporan penting sambil menjelaskan alasannya","Kamu diminta lembur setiap hari tanpa bayaran, dilarang istirahat, dan diancam tidak lulus magang bila menolak","Kamu diminta merevisi laporan karena datanya kurang lengkap","Ada rapat evaluasi mingguan yang membahas target tim"],a:1,e:"Tekanan wajar punya alasan dan batas. Lembur terus-menerus tanpa hak, larangan istirahat, dan ancaman adalah tanda eksploitasi."},
{b:1,l:2,q:"Supervisor berkata, “Laporanmu terlambat dua hari dan tiga tabel angkanya salah. Tolong cek ulang sebelum dikirim.” Pernyataan ini termasuk...",o:["Serangan pribadi karena nadanya tegas","Umpan balik profesional karena fokus pada hasil kerja dan memberi arahan perbaikan","Tanda lingkungan kerja toxic","Kritik yang sebaiknya diabaikan"],a:1,e:"Umpan balik profesional membahas hasil kerja secara spesifik dan memberi arahan perbaikan. Pisahkan isi pesan dari nadanya."},
{b:1,l:2,q:"Langkah pertama yang disarankan saat menerima kritik adalah...",o:["Langsung mencari alasan pembenaran","Mengambil jeda dan napas panjang sebelum merespons","Membalas dengan mengkritik balik","Menyangkal kritik demi menjaga ego"],a:1,e:"Jeda reaktif (pause) mematikan refleks defensif sebelum kamu merespons."},
{b:1,l:2,q:"Setelah gagal psikotes, pernyataan mana yang mencerminkan ketahanan mental (resilience)?",o:["“Aku memang orang yang gagal.”","“Aku gagal di tes hari ini. Aku akan cari tahu bagian mana yang perlu dilatih.”","“Tes seperti ini tidak adil, jadi tidak perlu dipikirkan.”","“Aku tidak akan ikut tes lagi.”"],a:1,e:"Kegagalan adalah peristiwa, bukan identitas. Post-mortem membantu menemukan strategi untuk percobaan berikutnya."},
{b:1,l:3,q:"Kebahagiaan eudaimonik adalah...",o:["Kesenangan sesaat dari hiburan atau barang baru","Kepuasan mendalam dari pemenuhan potensi diri dan tujuan hidup","Kondisi euforia tanpa pernah sedih","Kebahagiaan yang didapat dari pujian orang lain"],a:1,e:"Eudaimonik berasal dari pemenuhan potensi dan tujuan hidup, berbeda dari kesenangan hedonis yang sesaat."},
{b:1,l:3,q:"Praktik gratitude journaling yang disarankan adalah...",o:["Menuliskan semua kekesalan agar cepat lega","Menuliskan 3–5 hal kecil namun bermakna yang disyukuri setiap hari","Membandingkan pencapaian diri dengan teman","Menulis target besar setiap pagi"],a:1,e:"Menuliskan 3–5 hal yang disyukuri setiap hari membantu otak melawan bias negatif dan menurunkan hormon stres."},
{b:2,l:0,q:"Perbedaan utama berpikir sistem dan pola pikir linear adalah...",o:["Berpikir sistem selalu lebih cepat","Berpikir sistem melihat hubungan timbal balik antarbagian, termasuk lingkaran umpan balik","Pola pikir linear melihat semua bagian sekaligus","Berpikir sistem hanya dipakai di bidang teknik"],a:1,e:"Pola pikir linear melihat satu sebab dan satu akibat; berpikir sistem melihat hubungan dan feedback loop."},
{b:2,l:0,q:"“Makin sering latihan wawancara, makin lancar menjawab, makin percaya diri, sehingga makin rajin berlatih.” Ini adalah contoh...",o:["Balancing loop","Reinforcing loop","Pola pikir linear","Dilema palsu"],a:1,e:"Lingkaran penguat (reinforcing loop) terjadi ketika perubahan memperkuat dirinya sendiri."},
{b:2,l:1,q:"Manakah pernyataan yang merupakan fakta?",o:["“Perusahaan itu tempat kerja paling keren.”","“Kalau seminggu tidak dibalas, pasti aku ditolak.”","“Batas pengiriman lamaran tercantum 30 Juni di situs resmi perusahaan.”","“Semua HRD tidak suka lulusan SMK.”"],a:2,e:"Fakta dapat dibuktikan. Pilihan lain adalah opini, asumsi, dan generalisasi tergesa-gesa."},
{b:2,l:1,q:"Kamu menerima tawaran kerja yang meminta biaya pendaftaran Rp150.000, menjanjikan gaji tidak wajar, dan memakai email gratisan. Langkah berpikir kritis yang tepat adalah...",o:["Segera transfer agar tidak kehabisan kuota","Mengecek situs resmi perusahaan dan sumber lain, serta tidak mentransfer uang","Membagikannya ke grup supaya teman-teman ikut melamar","Percaya karena banyak orang sudah mendaftar"],a:1,e:"Cek sumber resmi dan bandingkan informasi. Biaya rekrutmen dan gaji tidak wajar adalah tanda lowongan palsu."},
{b:2,l:2,q:"Yoga lulusan SMK TKJ bercita-cita menjadi network engineer, belum punya sertifikasi, dan tabungannya terbatas. Keputusan karier yang paling realistis adalah...",o:["Hanya melamar ke perusahaan multinasional besar","Menunggu sampai punya uang untuk kursus mahal sebelum melamar","Melamar sebagai teknisi lapangan sambil belajar materi sertifikasi secara bertahap","Berganti bidang karena merasa tidak mungkin berhasil"],a:2,e:"Keputusan realistis mencocokkan peluang dengan kapasitas: mulai dari posisi yang terjangkau sambil membangun kualifikasi."},
{b:2,l:2,q:"Dalam berpikir strategis, analisis situasi bertujuan memetakan...",o:["Peluang, tantangan, dan kapasitas sumber daya","Kesalahan orang lain","Hal-hal yang membuat kita bahagia","Daftar keinginan tanpa batas"],a:0,e:"Analisis situasi memetakan peluang (eksternal), tantangan (eksternal), dan sumber daya (internal)."},
{b:2,l:3,q:"Dalam metode STAR, bagian “A” (Action) berisi...",o:["Gambaran situasi atau konteks","Tugas yang menjadi tanggung jawabmu","Tindakan spesifik yang kamu lakukan","Hasil akhir yang dicapai"],a:2,e:"S = Situation, T = Task, A = Action (tindakan spesifikmu), R = Result."},
{b:2,l:3,q:"Pewawancara bertanya, “Ceritakan saat kamu menyelesaikan masalah.” Jawaban mana yang paling sesuai dengan metode STAR?",o:["“Saya orangnya pekerja keras dan pantang menyerah.”","“Saat PKL, antrean servis sering lebih dari dua jam. Saya bertugas mencatat antrean, lalu membuat jadwal di spreadsheet dan pengingat WhatsApp. Waktu tunggu turun menjadi sekitar 45 menit.”","“Masalahnya selesai karena bantuan teman-teman.”","“Saya belum pernah punya masalah.”"],a:1,e:"Jawaban STAR memuat situasi, tugas, tindakan spesifik, dan hasil yang terukur."},
{b:2,l:3,q:"Urutan siklus pembelajaran berbasis pengalaman (Kolb) yang benar adalah...",o:["Konsep abstrak → pengalaman konkret → eksperimen aktif → observasi reflektif","Pengalaman konkret → observasi reflektif → konsep abstrak → eksperimen aktif","Eksperimen aktif → konsep abstrak → pengalaman konkret → observasi reflektif","Observasi reflektif → eksperimen aktif → pengalaman konkret → konsep abstrak"],a:1,e:"Mengalami, merenungkan, menarik pelajaran, lalu mencoba cara baru."},
{b:2,l:4,q:"Aturan brainstorming yang tepat adalah...",o:["Langsung mengkritik ide yang terdengar aneh","Mengutamakan jumlah ide dan menunda penilaian","Hanya orang paling senior yang boleh menyampaikan ide","Berhenti di ide pertama yang bagus"],a:1,e:"Brainstorming mengutamakan kuantitas ide dan menunda kritik sampai tahap memilih."},
{b:2,l:4,q:"Kamu ragu menyampaikan ide di rapat karena takut dianggap aneh. Cara mengatasi hambatan kreativitas (mental block) ini adalah...",o:["Diam saja sampai yakin idenya sempurna","Memisahkan tahap mencari ide dari tahap menilai ide, dengan aturan “tidak ada ide bodoh”","Meniru ide orang lain saja","Menunggu disuruh atasan"],a:1,e:"Takut dinilai adalah mental block umum. Pisahkan waktu mencari ide dari waktu memilih ide."}
];

